window.__finlexDocLoaded(10003,{"id":10003,"articles":[{"id":1000006,"no":"Overview","heading":"Scope & Key Requirements (Public Summary)","text":"Deals with the appointment and eligibility of the engagement quality reviewer (EQR) and the reviewer's responsibilities relating to the performance and documentation of an engagement quality review.","seq":0},{"id":1000007,"no":"ISQM 2.17–27","heading":"Engagement Quality Reviewer Eligibility, Cooling-Off & Review","text":"• Eligibility (ISQM 2.18–20): reviewer must have competence, capabilities, authority, and objectivity; requires a mandatory 2-year cooling-off period before a former engagement partner can serve as EQR for the same entity (ISQM 2.19(b)).\n• Performance & timing (ISQM 2.24–26): review significant judgements and conclusions at appropriate points throughout the engagement; engagement report CANNOT be dated before the EQR notifies completion (converged with China QMS 5102).","seq":1},{"id":1000008,"no":"Official Access","heading":"Official Handbook & Reference Entry","text":"Official source (IAASB 2026 Handbook): https://www.iaasb.org/publications/2026-handbook-international-quality-management-auditing-review-sustainability-and-other-assurance\nStatus: in_force. Detailed paragraph-level summaries and practice notes can be expanded incrementally.","seq":2}]});
